<script setup lang="ts">
import {computed} from 'vue'
import {MONSTER_ABILITIES,monsterSigned,monsterModifier,monsterChallenge} from '../../../shared/monster-statblock'
import {compileMonster,monsterPB,MONSTER_SECTIONS,SKILL_ABILITIES,type MonsterDraft,type MonsterStep} from '../../../shared/monster-workshop'
import MonsterDetailsEditor from './MonsterDetailsEditor.vue'
const props=defineProps<{draft:MonsterDraft;step:MonsterStep}>()
const statblock=computed(()=>compileMonster(props.draft)),remainingSections=MONSTER_SECTIONS.filter(s=>['legendary-actions','mythic-actions','lair-actions','regional-effects'].includes(s.key))
function optionalNumber(event:Event,set:(value:number|null)=>void){const v=(event.target as HTMLInputElement).value;set(v===''?null:Number(v))}
</script>
<template>
<template v-if="step==='identity'"><h3>Creature</h3><div class="mw-fields"><label class="mw-full">Name<input v-model="draft.name" maxlength="250"></label><label>Size<select v-model="draft.size"><option>Tiny</option><option>Small</option><option>Medium</option><option>Large</option><option>Huge</option><option>Gargantuan</option></select></label><label>Creature type<input v-model="draft.type" list="mw-types" maxlength="250"><datalist id="mw-types"><option v-for="t in ['aberration','beast','celestial','construct','dragon','elemental','fey','fiend','giant','humanoid','monstrosity','ooze','plant','undead']" :key="t">{{t}}</option></datalist></label><label>Subtype / tag<input v-model="draft.subtype" maxlength="250"></label><label>Alignment<input v-model="draft.alignment" maxlength="250"></label><label>Short name in rules<input v-model="draft.shortName" maxlength="250"></label><label>Plural name in rules<input v-model="draft.plural" maxlength="250"></label><label class="mw-full">Source collection<input v-model="draft.source" maxlength="250"></label><label class="mw-full">Description / lore<textarea v-model="draft.description" rows="4" maxlength="20000"></textarea></label></div></template>
      <template v-else-if="step==='statistics'"><h3>Statistics</h3><div class="mw-abilities"><label v-for="a in MONSTER_ABILITIES" :key="a">{{a.toUpperCase()}}<input v-model.number="draft.scores[a]" type="number" min="1" max="50"><small>{{monsterSigned(monsterModifier(draft.scores[a]))}}</small></label></div><div class="mw-fields"><label>Challenge rating<select v-model.number="draft.cr"><option v-for="cr in [0,0.125,0.25,0.5,...Array.from({length:30},(_,i)=>i+1)]" :key="cr" :value="cr">{{monsterChallenge(cr)}}</option></select></label><label>XP (optional)<input :value="draft.xp??''" type="number" min="0" max="1000000000" @input="optionalNumber($event,v=>draft!.xp=v)"></label><label>Custom challenge text<input v-model="draft.crText" placeholder="Blank uses the numeric CR" maxlength="250"></label><label>Proficiency bonus override<input :value="draft.pbOverride??''" type="number" min="0" max="20" :placeholder="String(monsterPB(draft))" @input="optionalNumber($event,v=>draft!.pbOverride=v)"></label></div><p class="hw-hint">Blank overrides use calculated values. CR is chosen by you, not an automatic assessment of encounter balance.</p><h3>Hit points</h3><div class="mw-fields"><label>Hit dice count<input v-model.number="draft.hp.count" type="number" min="1" max="999"></label><label>Die size<select v-model.number="draft.hp.die"><option v-for="die in [4,6,8,10,12,20]" :key="die" :value="die">d{{die}}</option></select></label></div><label class="mw-check"><input v-model="draft.hp.useCon" type="checkbox">Use CON modifier for each hit die</label><div class="mw-fields"><label>Custom dice modifier<input v-model.number="draft.hp.modifier" :disabled="draft.hp.useCon" type="number" min="-100000" max="100000"></label><label>Override average HP (optional)<input :value="draft.hp.override??''" type="number" min="1" max="10000000" @input="optionalNumber($event,v=>draft!.hp.override=v)"></label></div><p class="mw-calculation">{{statblock.extended?.hpText||statblock.hitPoints||'Not recorded'}} HP <span v-if="statblock.hitDice">({{statblock.hitDice}})</span></p></template>
      <template v-else-if="step==='defenses'"><h3>Defenses &amp; movement</h3><div class="mw-fields"><label>Armor calculation<select v-model="draft.armor.mode"><option value="unarmored">Unarmored (10 + DEX)</option><option value="natural">Natural armor</option><option value="leather">Leather armor (11 + DEX)</option><option value="scale">Scale mail (14 + DEX, max 2)</option><option value="plate">Plate armor (18)</option><option value="custom">Custom AC</option></select></label><label v-if="['natural','custom'].includes(draft.armor.mode)">Base AC<input v-model.number="draft.armor.base" type="number" min="0" max="100"></label></div><template v-if="draft.armor.mode==='natural'"><label class="mw-check"><input v-model="draft.armor.dex" type="checkbox">Add DEX modifier</label><label>DEX cap (optional)<input :value="draft.armor.dexCap??''" type="number" min="0" max="20" @input="optionalNumber($event,v=>draft!.armor.dexCap=v)"></label></template><label class="mw-check"><input v-model="draft.armor.shield" type="checkbox">Add a shield (+2 AC)</label><label>Armor note<input v-model="draft.armor.note" maxlength="250" placeholder="Blank uses the selected armor description"></label><p class="mw-calculation">Armor Class {{statblock.extended?.armorText||statblock.armorClass[0]?.value||'Not recorded'}}</p><div class="mw-fields"><label v-for="key in (['walk','burrow','climb','fly','swim'] as const)" :key="key">{{key}} speed (ft.)<input v-model.number="draft.movement[key]" type="number" min="0" max="100000"></label><label>Custom movement description<input v-model="draft.movement.custom" maxlength="2000" placeholder="Overrides the speed list"></label></div><label class="mw-check"><input v-model="draft.movement.hover" type="checkbox">Can hover while flying</label><details><summary>Saving throws &amp; skill proficiencies</summary><div class="mw-checks"><label v-for="a in MONSTER_ABILITIES" :key="a" class="mw-check"><input v-model="draft.saves" :value="a" type="checkbox">{{a.toUpperCase()}}</label></div><div class="mw-fields"><label v-for="name in Object.keys(SKILL_ABILITIES)" :key="name">{{name}}<select v-model.number="draft.skills[name]"><option :value="0">Not proficient</option><option :value="1">Proficient</option><option :value="2">Expertise</option></select></label></div><details><summary>Fixed save and skill bonuses</summary><div class="mw-fields"><label v-for="a in MONSTER_ABILITIES" :key="a">{{a.toUpperCase()}} save override<input :value="draft.saveOverrides[a]??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>v===null?delete draft!.saveOverrides[a]:draft!.saveOverrides[a]=v)"></label><label v-for="name in Object.keys(draft.skills).filter(n=>draft!.skills[n])" :key="name">{{name}} override<input :value="draft.skillOverrides[name]??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>v===null?delete draft!.skillOverrides[name]:draft!.skillOverrides[name]=v)"></label></div></details></details><h3>Resistances &amp; immunities</h3><div class="mw-fields"><label>Damage vulnerabilities<input v-model="draft.vulnerabilities" maxlength="2000"></label><label>Damage resistances<input v-model="draft.resistances" maxlength="2000" placeholder="Include conditions, such as nonmagical attacks"></label><label>Damage immunities<input v-model="draft.damageImmunities" maxlength="2000"></label><label>Condition immunities<input v-model="draft.conditionImmunities" maxlength="2000"></label></div><details><summary>Senses &amp; languages</summary><div class="mw-fields"><label v-for="key in (['blindsight','darkvision','tremorsense','truesight'] as const)" :key="key">{{key}} (ft.)<input v-model.number="draft.senses[key]" type="number" min="0" max="100000"></label><label>Passive Perception override<input :value="draft.passiveOverride??''" type="number" min="-100" max="100" @input="optionalNumber($event,v=>draft!.passiveOverride=v)"></label><label>Telepathy (ft.)<input v-model.number="draft.telepathy" type="number" min="0" max="100000"></label><label class="mw-full">Languages<input v-model="draft.languages" maxlength="2000"></label></div><label class="mw-check"><input v-model="draft.senses.blindBeyond" type="checkbox">Blind beyond blindsight radius</label><label class="mw-check"><input v-model="draft.understandsOnly" type="checkbox">Understands these languages but cannot speak</label></details></template>
      <template v-else-if="step==='advanced'"><h3>Advanced rules</h3><p class="hw-hint">Optional introductions and end notes for legendary, mythic, lair and regional rules. Add the individual actions under Traits &amp; actions.</p><details v-for="s in remainingSections" :key="s.key"><summary>{{s.name}}</summary><label>Introduction<textarea v-model="draft.introductions[s.key]" rows="4" maxlength="20000"></textarea></label><label>End note<textarea v-model="draft.endNotes[s.key]" rows="3" maxlength="20000"></textarea></label></details><p class="hw-hint">Written rules do not automatically execute combat effects, targeting or dice rolls.</p></template>
      <MonsterDetailsEditor :key="draft.id+step" :monster="draft" :step="step" /></template>